function coinsSaved(n: number): number {
  const f = Math.floor(n / 7), r = n % 7;
  const fullWeeks = (7 * f * (f + 1)) / 2 + 21 * f;
  const lastWeek = r * (f + 1) + (r * (r - 1)) / 2;
  return fullWeeks + lastWeek;
}

